"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([[1477],{10:n=>{n.exports=JSON.parse('{"blogPosts":[{"id":"animating-link-underline","metadata":{"permalink":"/blog/animating-link-underline","source":"@site/blog/2023-06-03-animation-link-underline/index.mdx","title":"\u5982\u4f55\u4e3a\u94fe\u63a5\u6dfb\u52a0\u751f\u52a8\u7684\u4e0b\u5212\u7ebf\u52a8\u753b","description":"\u7f51\u9875\u4e2d ` \u6807\u7b7e\u662f\u5e26\u6709\u5982\u4e0b\u8fd9\u6837\u4e00\u4e2a\u4e0b\u5212\u7ebf\u7684\u6837\u5f0f\uff0c\u6211\u4eec\u4e5f\u53ef\u4ee5\u901a\u8fc7 text-decoration` \u5c5e\u6027\u53bb\u8bbe\u7f6e\u6210\u522b\u7684\u6837\u5f0f\u3002","date":"2023-06-03T00:00:00.000Z","formattedDate":"2023\u5e746\u67083\u65e5","tags":[{"label":"\u4e0b\u5212\u7ebf","permalink":"/blog/tags/\u4e0b\u5212\u7ebf"},{"label":"\u52a8\u753b","permalink":"/blog/tags/\u52a8\u753b"},{"label":"\u94fe\u63a5","permalink":"/blog/tags/\u94fe\u63a5"}],"readingTime":1.905,"hasTruncateMarker":false,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","email":"fants0230@sina.com","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=48&v=4","key":"timfan"}],"frontMatter":{"slug":"animating-link-underline","title":"\u5982\u4f55\u4e3a\u94fe\u63a5\u6dfb\u52a0\u751f\u52a8\u7684\u4e0b\u5212\u7ebf\u52a8\u753b","authors":["timfan"],"tags":["\u4e0b\u5212\u7ebf","\u52a8\u753b","\u94fe\u63a5"],"enableComments":true,"draft":false},"nextItem":{"title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","permalink":"/blog/tree-views"}},"content":"\u7f51\u9875\u4e2d `<a>` \u6807\u7b7e\u662f\u5e26\u6709\u5982\u4e0b\u8fd9\u6837\u4e00\u4e2a\u4e0b\u5212\u7ebf\u7684\u6837\u5f0f\uff0c\u6211\u4eec\u4e5f\u53ef\u4ee5\u901a\u8fc7 `text-decoration` \u5c5e\u6027\u53bb\u8bbe\u7f6e\u6210\u522b\u7684\u6837\u5f0f\u3002\\n\\nimport styles from \'./style.module.css\'\\nimport clsx from \'clsx\'\\n\\nexport const GenerateLinkText = ({ cln, text=\'Hover This Text\' }) => (\\n  <div className={clsx(styles.outDiv)}>\\n    <a className={clsx(styles[cln])}>{ text }</a>\\n  </div>\\n);\\n\\n<GenerateLinkText cln=\'defaultALink\' />\\n\\n\u800c\u6211\u4eec\u4eca\u5929\u8981\u8ba8\u8bba\u7684\u4e0b\u5212\u7ebf\u52a8\u753b\uff0c\u662f\u65e0\u6cd5\u76f4\u63a5\u901a\u8fc7\u54ea\u4e2a CSS \u5c5e\u6027\u8bbe\u7f6e\u7684\u3002\u6211\u4eec\u53ea\u80fd\u901a\u8fc7\u4f2a\u9020\u7684\u65b9\u5f0f\u6a21\u62df\u51fa\u4e00\u4e2a\u4e0b\u5212\u7ebf\u7684\u6548\u679c\u3002\\n\\n\u9996\u5148\u6211\u4eec\u5c06 `<a>` \u6807\u7b7e\u7684\u9ed8\u8ba4\u4e0b\u5212\u7ebf\u53bb\u6389\uff0c\u7136\u540e\u5c06\u9f20\u6807 hover \u540e\u7684\u5b57\u4f53\u989c\u8272\u4fdd\u6301\u4e00\u81f4\u3002\\n\\n``` css\\na {\\n  position: relative;\\n  color: #000;\\n  text-decoration: none;\\n}\\n\\na:hover {\\n  color: #000;\\n}\\n```\\n\\n\u63a5\u4e0b\u6765\u6211\u4eec\u901a\u8fc7\u4f2a\u5143\u7d20 `::before` \u8bbe\u7f6e\u5b83\u7684\u9ad8\u5ea6\uff0c\u5e76\u4e14\u586b\u5145\u989c\u8272\u6765\u6a21\u62df\u6210\u8fb9\u6846\uff0c\u5c06\u5b83\u7edd\u5bf9\u5b9a\u4f4d\u5728\u6587\u5b57\u7684\u5e95\u90e8\u3002\\n\\n``` css\\na::before {\\n  content: \\"\\";\\n  position: absolute;\\n  display: block;\\n  width: 100%;\\n  height: 2px;\\n  bottom: 0;\\n  left: 0;\\n  background-color: #000;\\n  transform: scaleX(0);\\n  transition: transform 0.3s ease;\\n}\\n```\\n\\n\u6211\u4eec\u901a\u8fc7 CSS \u7684\u52a8\u753b\u5c5e\u6027 `transform` \u5c06\u8fb9\u6846 `X` \u8f74\u4e0a\u7684\u89c4\u6a21\u4ece 0 \u53d8\u5230 1 \u6a21\u62df\u51fa\u4ece\u65e0\u5230\u6709\u7684\u8fc7\u7a0b\u3002\\n\\n``` css\\na:hover::before {\\n  transform: scaleX(1);\\n}\\n```\\n\\n\u6700\u540e\u7684\u6548\u679c\u5982\u4e0b\uff08\u5c06\u9f20\u6807\u6307\u9488\u79fb\u52a8\u5230\u6587\u5b57\u4e0a\uff09\uff1a\\n\\n<GenerateLinkText cln=\'borderALink\' />\\n\\n\u73b0\u5728\u52a8\u753b\u7684\u8d77\u59cb\u4f4d\u7f6e\u9ed8\u8ba4\u662f\u4ece\u4e2d\u95f4\u5411\u5de6\u53f3\u4e24\u8fb9\u5c55\u5f00\u7684\u3002`transform` \u91cc\u8fd8\u6709\u8fd9\u6837\u4e00\u4e2a\u5c5e\u6027 `transform-orgin`\uff0c\u4f5c\u7528\u5c31\u662f\u6307\u5b9a\u52a8\u753b\u662f\u4ece\u54ea\u91cc\u5f00\u59cb\u7684\u3002\u5982\u679c\u4ece\\n\u5de6\u8fb9\u5f00\u59cb\uff0c\u5373 `transform-orgin: top left`\u3002\\n\\n<GenerateLinkText cln=\'animatingLeftALink\' text=\'Hover me (from left)\' />\\n\\n\u53f3\u8fb9\u5219\u662f\uff1a`transform-orgin: top right`\u3002\\n\\n<GenerateLinkText cln=\'animatingRightALink\' text=\'Hover me (from right)\' />"},{"id":"tree-views","metadata":{"permalink":"/blog/tree-views","source":"@site/blog/2023-05-26-tree-views-in-css/index.mdx","title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","description":"\u4e00\u4e2a\u6811\u72b6\u7ed3\u6784\u7684\u89c6\u56fe\u53ef\u4ee5\u4ec5\u4ec5\u7531 HTML \u548c CSS \u4ee3\u7801\u6765\u5b9e\u73b0\u800c\u4e0d\u7528\u501f\u52a9 JavaScript\u3002\u7f51\u9875\u7684\u65e0\u969c\u788d\u8bbf\u95ee\u529f\u80fd\u4f1a\u5c06\u6811\u72b6\u89c6\u56fe\u89c6\u4e3a\u5d4c\u5957\u7684\u5e76\u5305\u542b\u5176\u5b83\u7ec4\u4ef6\u5185\u5bb9\u7684\u5217\u8868\uff0c\u5e76\u4e14\u81ea\u52a8\u652f\u6301\u6807\u51c6\u952e\u76d8\u4ea4\u4e92\u3002","date":"2023-05-26T00:00:00.000Z","formattedDate":"2023\u5e745\u670826\u65e5","tags":[{"label":"\u6811\u72b6","permalink":"/blog/tags/\u6811\u72b6"},{"label":"\u89c6\u56fe","permalink":"/blog/tags/\u89c6\u56fe"}],"readingTime":7.505,"hasTruncateMarker":true,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","email":"fants0230@sina.com","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=48&v=4","key":"timfan"}],"frontMatter":{"slug":"tree-views","title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","authors":["timfan"],"tags":["\u6811\u72b6","\u89c6\u56fe"],"enableComments":true},"prevItem":{"title":"\u5982\u4f55\u4e3a\u94fe\u63a5\u6dfb\u52a0\u751f\u52a8\u7684\u4e0b\u5212\u7ebf\u52a8\u753b","permalink":"/blog/animating-link-underline"},"nextItem":{"title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","permalink":"/blog/detecting-caps-lock"}},"content":"\u4e00\u4e2a\u6811\u72b6\u7ed3\u6784\u7684\u89c6\u56fe\u53ef\u4ee5\u4ec5\u4ec5\u7531 HTML \u548c CSS \u4ee3\u7801\u6765\u5b9e\u73b0\u800c\u4e0d\u7528\u501f\u52a9 JavaScript\u3002\u7f51\u9875\u7684\u65e0\u969c\u788d\u8bbf\u95ee\u529f\u80fd\u4f1a\u5c06\u6811\u72b6\u89c6\u56fe\u89c6\u4e3a\u5d4c\u5957\u7684\u5e76\u5305\u542b\u5176\u5b83\u7ec4\u4ef6\u5185\u5bb9\u7684\u5217\u8868\uff0c\u5e76\u4e14\u81ea\u52a8\u652f\u6301\u6807\u51c6\u952e\u76d8\u4ea4\u4e92\u3002\\n\\nimport styles from \\"./style.module.css\\"\\nimport clsx from \'clsx\';\\nexport const TreeViews = ({ ulClsName, expandAll }) => (\\n  <ul className={clsx(styles.tree, styles[ulClsName])}>\\n    <li>\\n      <details open>\\n        <summary>Giant planets</summary>\\n        <ul>\\n          <li>\\n            <details open={ expandAll }>\\n              <summary>Gas giants</summary>\\n              <ul>\\n                <li>Jupiter</li>\\n                <li>Saturn</li>\\n              </ul>\\n            </details>\\n          </li>\\n          <li>\\n            <details open={ expandAll }>\\n              <summary>Ice giants</summary>\\n              <ul>\\n                <li>Uranus</li>\\n                <li>Neptune</li>\\n              </ul>\\n            </details>\\n          </li>\\n        </ul>\\n      </details>\\n    </li>\\n  </ul>\\n)\\n\\n<TreeViews ulClsName=\'displaytree\' />\\n\\n### HTML \u4ee3\u7801\u7ed3\u6784\\n\\n\u9996\u5148\u6dfb\u52a0\u5982\u4e0b\u7684\u5d4c\u5957\u7684\u5217\u8868\u7ed3\u6784\u4ee3\u7801\uff1a\\n\\n\x3c!--truncate--\x3e\\n\\n``` html\\n<ul>\\n  <li>\\n    Giant planets\\n    <ul>\\n      <li>\\n        Gas giants\\n        <ul>\\n          <li>Jupiter</li>\\n          <li>Saturn</li>\\n        </ul>\\n      </li>\\n      <li>\\n        Ice giants\\n        <ul>\\n          <li>Uranus</li>\\n          <li>Neptune</li>\\n        </ul>\\n      </li>\\n    </ul>\\n  </li>\\n</ul>\\n```\\n\\n\u4e3a\u4e86\u65b9\u4fbf\u8bbe\u7f6e\u6837\u5f0f\uff0c\u6211\u4eec\u7ed9\u6700\u5916\u5c42\u7684 `<ul>` \u5143\u7d20\u6dfb\u52a0\u4e00\u4e2a\u7c7b\u540d\u3002\u7b2c\u4e00\u5c42\u7684 `<li>` \u5143\u7d20\u4e0b\u9762\u90fd\u5d4c\u5957\u4e86\u4e00\u4e2a\u5217\u8868\uff0c\u4e3a\u4e86\u5b9e\u73b0\u5c55\u5f00\u7684\u6548\u679c\uff0c\u6211\u4eec\u5c06 `<li>` \u91cc\u9762\u7684\u5143\u7d20\u90fd\u653e\u5728 `<details>` \u548c `<summary>` \u4e0b\u9762\u3002\\n\u7136\u540e\u901a\u8fc7 `open` \u5c5e\u6027\u6765\u8bbe\u7f6e\u9ed8\u8ba4\u5c55\u5f00\u7684\u5d4c\u5957\u5217\u8868\u3002\\n\\n``` html\\n<ul class=\\"tree\\">\\n  <li>\\n    <details open>\\n      <summary>Giant planets</summary>\\n      <ul>\\n        <li>\\n          <details>\\n            <summary>Gas giants</summary>\\n            <ul>\\n              <li>Jupiter</li>\\n              <li>Saturn</li>\\n            </ul>\\n          </details>\\n        </li>\\n        <li>\\n          <details>\\n            <summary>Ice giants</summary>\\n            <ul>\\n              <li>Uranus</li>\\n              <li>Neptune</li>\\n            </ul>\\n          </details>\\n        </li>\\n      </ul>\\n    </details>\\n  </li>\\n</ul>\\n```\\n\\n\u5982\u4e0b\uff0c\u8fd9\u662f\u6ca1\u6709\u6dfb\u52a0\u4efb\u4f55\u6837\u5f0f\u7684\uff1a\\n\\n<TreeViews ulClsName=\'none\' />\\n\\n\u6d4f\u89c8\u5668\u4e3a `<details>` \u5143\u7d20\u63d0\u4f9b\u4e86\u63d0\u4f9b\u5c55\u5f00\u548c\u6298\u53e0\u5d4c\u5957\u5217\u8868\u7684\u80fd\u529b\uff0c\u4f46\u662f\u9879\u76ee\u7b26\u53f7\u548c\u7bad\u5934\u7b26\u53f7\u90fd\u663e\u793a\u5bb9\u6613\u8ba9\u4eba\u4ea7\u751f\u56f0\u60d1\u3002\u6211\u4eec\u8fdb\u884c\u7ec4\u5408\u6539\u53d8\u4e0b\u6837\u5f0f\u3002\\n\\n### \u81ea\u5b9a\u4e49\u6837\u5f0f\\n\\n\u6709\u4e24\u4e2a\u7ef4\u5ea6\u4f1a\u5f71\u54cd\u6811\u89c6\u56fe\u7684\u5e03\u5c40\uff1a\u884c\u95f4\u8ddd\uff08\u7b49\u4e8e\u6587\u672c\u7684\u884c\u9ad8\uff09\u548c\u5217\u8868\u7b26\u53f7\u7684\u534a\u5f84\u3002 \u9996\u5148\u6211\u4eec\u7ed9\u8fd9\u4e24\u4e2a\u7ef4\u5ea6\u7684\u6570\u636e\u901a\u8fc7 CSS \u81ea\u5b9a\u4e49\u5c5e\u6027\u5b9a\u4e49\u5e38\u91cf\u4f9b\u540e\u9762\u4f7f\u7528\uff1a\\n\\n``` css\\n.tree{\\n  --spacing : 1.5rem;\\n  --radius  : 10px;\\n}\\n```\\n\\n\u867d\u7136\u6211\u4eec\u901a\u5e38\u4f1a\u6839\u636e\u6587\u672c\u5927\u5c0f\u4f7f\u7528\u76f8\u5bf9\u5355\u4f4d\u6765\u7f29\u653e\u7528\u6237\u754c\u9762\u63a7\u4ef6\uff0c\u4f46\u5bf9\u4e8e\u5217\u8868\u7b26\u53f7\u8fd8\u662f\u4f7f\u7528\u4e86\u5408\u7406\u7684\u56fa\u5b9a\u5927\u5c0f\uff0c\u907f\u514d\u592a\u5927\u540e\u8005\u592a\u5c0f\u3002\\n\\n#### \u5de6\u8fb9\u8ddd\\n\\n\u63a5\u7740\u6211\u4eec\u6765\u7ed9\u5217\u8868\u6539\u53d8\u4e0b\u6837\u5f0f\uff0c\u5728\u5de6\u4fa7\u6dfb\u52a0\u4e00\u4e2a\u5185\u8fb9\u8ddd\uff0c\u4e3a\u6811\u72b6\u7684\u7ebf\u6761\u548c\u5c55\u5f00\u6536\u7f29\u7b26\u53f7\u817e\u51fa\u7a7a\u95f4\u3002\\n\\n``` css\\n.tree li{\\n  display      : block;\\n  position     : relative;\\n  padding-left : calc(2 * var(--spacing) - var(--radius) - 2px);\\n}\\n\\n.tree ul{\\n  margin-left  : calc(var(--radius) - var(--spacing));\\n  padding-left : 0;\\n}\\n```\\n\\n\u4e3a `li` \u6807\u7b7e\u8bbe\u7f6e `display: block` \u6d88\u9664\u9ed8\u8ba4\u7684\u5217\u8868\u7b26\u53f7\uff0c\u5de6\u8fb9\u8ddd\u7684\u503c\u662f\u901a\u8fc7\u4e0a\u9762\u7684\u5e38\u91cf\u8ba1\u7b97\u800c\u6765\u3002\u4e0b\u9762\u5bf9\u5d4c\u5957\u7684 `ul` \u8bbe\u7f6e\u8d1f\u8fb9\u8ddd\u6765\u8865\u507f\u5bf9 `li` \u8bbe\u7f6e\u7684\u7f29\u8fdb\u3002\\n\\n\u6709\u4e86\u4e0a\u9762\u7684\u6837\u5f0f\uff0c\u5728\u7ed9\u6240\u6709\u7684\u9ed8\u8ba4\u5217\u8868\u5c55\u5f00\uff0c\u5c31\u662f\u4e0b\u9762\u7684\u6837\u5f0f\uff1a\\n\\n<TreeViews ulClsName=\'displayPaddingTree\' expandAll={ true } />\\n\\n#### \u5782\u76f4\u7ebf\\n\\n\u63a5\u4e0b\u6765\u6211\u4eec\u6dfb\u52a0\u6811\u7ed3\u6784\u7684\u5782\u76f4\u7ebf\uff0c\u8fd9\u4e9b\u5782\u76f4\u7ebf\u6784\u6210\u5c06\u6bcf\u4e2a\u5217\u8868\u9879\u4ece\u5782\u76f4\u65b9\u5411\u4e32\u8054\u8d77\u6765\uff1a\\n\\n<TreeViews ulClsName=\'displayLineTree\' expandAll={ true } />\\n\\n#### \u6c34\u5e73\u7ebf\\n\\n\u6211\u4eec\u4f7f\u7528 CSS \u751f\u6210\u4e00\u6761\u6c34\u5e73\u7ebf\u5c06\u5782\u76f4\u7ebf\u548c\u5217\u8868\u524d\u7684\u7b26\u53f7\u8fdb\u884c\u8fde\u63a5\uff1a\\n\\n``` css\\n.tree ul li::before{\\n  content      : \'\';\\n  display      : block;\\n  position     : absolute;\\n  top          : calc(var(--spacing) / -2);\\n  left         : -2px;\\n  width        : calc(var(--spacing) + 2px);\\n  height       : calc(var(--spacing) + 1px);\\n  border       : solid #ddd;\\n  border-width : 0 0 2px 2px;\\n}\\n```\\n\\n\u8fd9\u6bb5 CSS \u4ee3\u7801\u540c\u65f6\u4e5f\u751f\u6210\u4e86\u4e00\u5c0f\u6bb5\u5782\u76f4\u65b9\u5411\u7684\u7ebf\u6761\u548c\u4e4b\u524d\u7684\u5782\u76f4\u7ebf\u6761\u91cd\u5408\u4e86\uff0c\u5f25\u8865\u4e86\u5782\u76f4\u7ebf\u548c\u6c34\u5e73\u7ebf\u4e4b\u95f4\u7684\u4e00\u5c0f\u6bb5\u95f4\u9699\u3002\u7ebf\u6761\u662f\u901a\u8fc7\u4f2a\u5143\u7d20\u8bbe\u7f6e\u6210\u77e9\u5f62\uff0c\u7136\u540e\u6dfb\u52a0\u5de6\u4fa7\u548c\u5e95\u90e8\u8fb9\u6846\u5b9e\u73b0\u7684\u3002\\n\\n<TreeViews ulClsName=\'displayVLineTree\' expandAll={ true } />\\n\\n#### \u5c55\u5f00\u9879\\n\\n\u4e0b\u9762\u6211\u4eec\u79fb\u9664 `summary` \u5143\u7d20\u81ea\u5e26\u9ed8\u8ba4\u7684\u7bad\u5934\u56fe\u6807\\n\\n``` css\\n.tree summary{\\n  display : block;\\n  cursor  : pointer;\\n}\\n\\n.tree summary::marker,\\n.tree summary::-webkit-details-marker{\\n  display : none;\\n}\\n\\n.tree summary:focus{\\n  outline : none;\\n}\\n\\n.tree summary:focus-visible{\\n  outline : 1px dotted #000;\\n}\\n```\\n\\n\u4e3a\u5143\u7d20 `summary` \u8bbe\u7f6e `display: block` \u662f\u4e3a\u4e86\u79fb\u9664\u9ed8\u8ba4\u7684\u524d\u9762\u7684\u7bad\u5934\u7b26\u53f7\u3002\u4e0b\u9762\u90a3\u6bb5\u7ed9 `::marker` \u8bbe\u7f6e\u7684 `display: none` \u4e3a\u89e3\u51b3 Safari \u6d4f\u89c8\u5668\u7684\u517c\u5bb9\u6027\u3002Safari \u6d4f\u89c8\u5668\u5728 `summary` \\n\u5468\u56f4\u663e\u793a\u4e86\u7126\u70b9\u6307\u793a\u5668\uff0c\u5373\u4f7f\u9f20\u6807\u6307\u9488\u800c\u4e0d\u662f\u952e\u76d8\u5bfc\u822a\u65f6\u4e5f\u662f\u5982\u6b64\uff0c\u56e0\u6b64\u6211\u4eec\u5220\u9664\u4e86\u5b83\u7684 `focus` \u72b6\u6001\u6837\u5f0f\uff0c\u7136\u540e\u4f7f\u7528 `:focus-visible` \u4f2a\u7c7b\u4e3a\u4f7f\u7528\u952e\u76d8\u5bfc\u822a\u7684\u8bbf\u95ee\u8005\u6dfb\u52a0\u56de\u6765\u3002\\n\\n\u6dfb\u52a0\u540e\u7684\u6837\u5f0f\uff1a\\n\\n<TreeViews ulClsName=\'displayArrowTree\' expandAll={ true } />\\n\\n#### \u6dfb\u52a0\u6811\u8282\u70b9\u7b26\u53f7\\n\\n\u6211\u4eec\u4f7f\u7528 [CSS \u751f\u6210\u5185\u5bb9](https://developer.mozilla.org/en-US/docs/Web/CSS/CSS_Generated_Content)\u6765\u521b\u5efa\u6811\u8282\u70b9\u7684\u6307\u793a\u7b26\u53f7\\n\\n``` css\\n.tree li::after,\\n.tree summary::before{\\n  content       : \'\';\\n  display       : block;\\n  position      : absolute;\\n  top           : calc(var(--spacing) / 2 - var(--radius));\\n  left          : calc(var(--spacing) - var(--radius) - 1px);\\n  width         : calc(2 * var(--radius));\\n  height        : calc(2 * var(--radius));\\n  border-radius : 50%;\\n  background    : #ddd;\\n}\\n```\\n\\n\u8fd9\u91cc\u6211\u4eec\u5229\u7528\u4f2a\u5143\u7d20\u540c\u65f6\u7ed9 `li` \u548c `summary` \u4e24\u4e2a\u5143\u7d20\u6dfb\u52a0\u4e86\u5706\u5f62\u7b26\u53f7\uff0c\u7531\u4e8e\u4f7f\u7528\u4e86\u7edd\u5bf9\u5b9a\u4f4d\uff0c\u4ed6\u4eec\u91cd\u5408\u5728\u4e00\u8d77\u3002top \u548c left \u7684\u503c\u6b63\u597d\u8ba9\u8fd9\u4e2a\u5706\u70b9\u7684\u5706\u5fc3\u5904\u4e8e\u5782\u76f4\u548c\u6c34\u5e73\u76f8\u4ea4\u7ebf\u7684\u89d2\u4e0a\u3002\\n\\n\u5e94\u7528\u6837\u5f0f\u540e\u663e\u793a\u5982\u4e0b\uff1a\\n\\n<TreeViews ulClsName=\'displayDotTree\' expandAll={ true } />\\n\\n#### \u5c55\u5f00\u6536\u7f29\u6309\u94ae\\n\\n\u6700\u540e\u6211\u4eec\u5b9e\u73b0\u5c55\u5f00\u6536\u7f29\u6309\u94ae\\n\\n``` css\\n.tree summary::before{\\n  content     : \'+\';\\n  z-index     : 1;\\n  background  : #696;\\n  color       : #fff;\\n  line-height : calc(2 * var(--radius) - 2px);\\n  text-align  : center;\\n}\\n\\n.tree details[open] > summary::before{\\n  content : \'\u2212\';\\n}\\n```\\n\\n\u5e94\u7528\u5b8c\u4e0a\u9762\u6837\u5f0f\u540e\uff0c\u6548\u679c\u5982\u4e0b\uff1a\\n\\n<TreeViews ulClsName=\'displaytree\' expandAll={ true } />\\n\\n### \u6700\u540e\\n\\n\u5b8c\u6574\u7684\u6837\u5f0f\u4ee3\u7801\\n\\n``` css\\n.tree{\\n  --spacing : 1.5rem;\\n  --radius  : 10px;\\n}\\n\\n.tree li{\\n  display      : block;\\n  position     : relative;\\n  padding-left : calc(2 * var(--spacing) - var(--radius) - 2px);\\n}\\n\\n.tree ul{\\n  margin-left  : calc(var(--radius) - var(--spacing));\\n  padding-left : 0;\\n}\\n\\n.tree ul li{\\n  border-left : 2px solid #ddd;\\n}\\n\\n.tree ul li:last-child{\\n  border-color : transparent;\\n}\\n\\n.tree ul li::before{\\n  content      : \'\';\\n  display      : block;\\n  position     : absolute;\\n  top          : calc(var(--spacing) / -2);\\n  left         : -2px;\\n  width        : calc(var(--spacing) + 2px);\\n  height       : calc(var(--spacing) + 1px);\\n  border       : solid #ddd;\\n  border-width : 0 0 2px 2px;\\n}\\n\\n.tree summary{\\n  display : block;\\n  cursor  : pointer;\\n}\\n\\n.tree summary::marker,\\n.tree summary::-webkit-details-marker{\\n  display : none;\\n}\\n\\n.tree summary:focus{\\n  outline : none;\\n}\\n\\n.tree summary:focus-visible{\\n  outline : 1px dotted #000;\\n}\\n\\n.tree li::after,\\n.tree summary::before{\\n  content       : \'\';\\n  display       : block;\\n  position      : absolute;\\n  top           : calc(var(--spacing) / 2 - var(--radius));\\n  left          : calc(var(--spacing) - var(--radius) - 1px);\\n  width         : calc(2 * var(--radius));\\n  height        : calc(2 * var(--radius));\\n  border-radius : 50%;\\n  background    : #ddd;\\n}\\n\\n.tree summary::before{\\n  content     : \'+\';\\n  z-index     : 1;\\n  background  : #696;\\n  color       : #fff;\\n  line-height : calc(2 * var(--radius) - 2px);\\n  text-align  : center;\\n}\\n\\n.tree details[open] > summary::before{\\n  content : \'\u2212\';\\n}\\n```"},{"id":"detecting-caps-lock","metadata":{"permalink":"/blog/detecting-caps-lock","source":"@site/blog/2023-05-25-detecting-caps-lock.mdx","title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","description":"\u5f00\u53d1\u4e2d\u4e3a\u4e86\u63d0\u5347\u7f51\u9875\u7684\u53ef\u7528\u6027\uff0c\u5728\u7f51\u9875\u4e2d\u68c0\u6d4b\u952e\u76d8\u5927\u5c0f\u5199\u952e caps lock \u5f00\u542f\u72b6\u6001\u5f88\u6709\u5fc5\u8981\uff0c\u5c24\u5176\u5728\u8f93\u5165\u5bc6\u7801\u7684\u65f6\u5019\uff0c\u6211\u4eec\u5e76\u4e0d\u80fd\u770b\u89c1\u8f93\u5165\u7684\u5b57\u7b26\u662f\u4ec0\u4e48\uff0c\u5982\u679c\u662f\u7531\u4e8e\u5927\u5c0f\u5199\u9519\u8bef\u6211\u4eec\u5e76\u4e0d\u80fd\u7b2c\u4e00\u65f6\u95f4\u611f\u77e5\u5230\u3002","date":"2023-05-25T00:00:00.000Z","formattedDate":"2023\u5e745\u670825\u65e5","tags":[{"label":"\u4fa6\u542c","permalink":"/blog/tags/\u4fa6\u542c"},{"label":"Capslock","permalink":"/blog/tags/capslock"}],"readingTime":2.365,"hasTruncateMarker":true,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","email":"fants0230@sina.com","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=48&v=4","key":"timfan"}],"frontMatter":{"slug":"detecting-caps-lock","title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","authors":["timfan"],"tags":["\u4fa6\u542c","Capslock"]},"prevItem":{"title":"\u7528 CSS \u5b9e\u73b0\u6811\u72b6\u89c6\u56fe","permalink":"/blog/tree-views"},"nextItem":{"title":"\u5f7b\u5e95\u4e86\u89e3 npm\u3001cnpm\u3001yarn\u3001pnpm \u51e0\u79cd\u5305\u7ba1\u7406\u5668","permalink":"/blog/package-tools"}},"content":"\u5f00\u53d1\u4e2d\u4e3a\u4e86\u63d0\u5347\u7f51\u9875\u7684\u53ef\u7528\u6027\uff0c\u5728\u7f51\u9875\u4e2d\u68c0\u6d4b\u952e\u76d8\u5927\u5c0f\u5199\u952e `caps lock` \u5f00\u542f\u72b6\u6001\u5f88\u6709\u5fc5\u8981\uff0c\u5c24\u5176\u5728\u8f93\u5165\u5bc6\u7801\u7684\u65f6\u5019\uff0c\u6211\u4eec\u5e76\u4e0d\u80fd\u770b\u89c1\u8f93\u5165\u7684\u5b57\u7b26\u662f\u4ec0\u4e48\uff0c\u5982\u679c\u662f\u7531\u4e8e\u5927\u5c0f\u5199\u9519\u8bef\u6211\u4eec\u5e76\u4e0d\u80fd\u7b2c\u4e00\u65f6\u95f4\u611f\u77e5\u5230\u3002\\n\\n\u5982\u4e0b\u5b9e\u4f8b\u6f14\u793a\uff0c\u5f53\u6211\u4eec\u5728\u5bc6\u7801\u8f93\u5165\u6846\u4e2d\u8f93\u5165\u5185\u5bb9\u65f6\uff0c\u5982\u679c\u6211\u4eec\u7684\u5927\u5c0f\u5199\u952e\u662f\u5f00\u542f\u7684\u72b6\u6001\uff0c\u5c31\u4f1a\u5f97\u5230\u201cCaps lock is on\u201d\u8fd9\u6837\u7684\u63d0\u793a\u4fe1\u606f\u3002\\n\\nimport { useState } from \'react\'\\nimport BrowserOnly from \'@docusaurus/BrowserOnly\'\\nexport const CapsLockDetect = () => {\\n  return (\\n    <BrowserOnly>\\n    {() => {\\n      const [ locked, setLocked ] = useState(false);\\n      window.addEventListener(\'keydown\', detect)\\n      window.addEventListener(\'keyup\', detect)\\n      function detect (e) {\\n        if (e.getModifierState(\'CapsLock\')) {\\n          setLocked(true)\\n        } else {\\n          setLocked(false)\\n        }\\n      }\\n      return (\\n        <div\\n          style={{\\n            backgroundColor: \'#eee\',\\n            padding: \'10px\',\\n            margin: \'0 0 20px\'\\n          }}>\\n          <input type=\'password\' placeholder=\\"Password\\" />\\n          { locked ? <div>Caps lock is on</div> : \'\' }\\n        </div>\\n      )\\n    }\\n    }\\n    </BrowserOnly>\\n  )\\n};\\n\\n<CapsLockDetect />\\n\\n\x3c!--truncate--\x3e\\n\\n\u867d\u7136\u76ee\u524d\u6d4f\u89c8\u5668\u8fd8\u6ca1\u6709\u63d0\u4f9b\u73b0\u6210\u7684 API \u6765\u67e5\u8be2 `caps lock` \u952e\u7684\u5f00\u542f\u7684\u72b6\u6001\uff0c\u4f46\u662f\u6211\u4eec\u53ef\u4ee5\u91c7\u7528\u5bf9\u6309\u952e `keyup` \u548c `keydown` \u4e8b\u4ef6\u7684\u76d1\u542c\uff0c\u7136\u540e\u901a\u8fc7 `KeyboardEvent` \u5bf9\u8c61\u7684\\n [getModifierState](https://developer.mozilla.org/en-US/docs/Web/API/KeyboardEvent/getModifierState) \u65b9\u6cd5\u6765\u83b7\u53d6\u3002\\n\\n\\n``` js\\nwindow.addEventListener(\'keydown\', detectCapsLock)\\nwindow.addEventListener(\'keyup\', detectCapsLock)\\n\\nfunction detectCapsLock(e) {\\n  if (e.getModifierState(\'CapsLock\')) {\\n    // caps lock is on\\n  } else {\\n    // caps lock is off\\n  }\\n}\\n```\\n\\n\u6211\u4eec\u5fc5\u987b\u540c\u65f6\u76d1\u542c `keyup` \u548c `keydown` \u6309\u952e\u4e8b\u4ef6\uff0c\u56e0\u4e3a\uff0c\u901a\u5e38\u60c5\u51b5\u4e0b\uff0c\u6d4f\u89c8\u5668\u4f1a\u5728\u67d0\u4e2a\u6309\u952e\u6309\u4e0b\u65f6\u89e6\u53d1 `keydown` \u4e8b\u4ef6\uff0c\u5728\u91ca\u653e\u8be5\u952e\u65f6\u89e6\u53d1 `keyup` \u4e8b\u4ef6\uff0c\u4f46\u662f\u5bf9\u4e8e\u952e\u76d8\u4e0a\u7684 `caps lock` \u952e\u800c\u8a00\uff0c\\n\u6bcf\u6b21\u6309\u4e0b\u53ea\u4f1a\u89e6\u53d1\u5176\u4e2d\u7684\u4e00\u4e2a\u4e8b\u4ef6\u3002\\n\\n\u5f53\u6211\u4eec\u6309\u4e0b `caps lock` \u952e\u4ee5\u6253\u5f00\u5927\u5199\u9501\u5b9a\u65f6\uff0c\u6240\u6709\u6d4f\u89c8\u5668\u4ec5\u53d1\u9001\u4e00\u4e2a keydown \u4e8b\u4ef6\u3002\u5f53\u6211\u4eec\u6309\u4e0b `caps lock` \u952e\u4ee5\u5173\u95ed\u5927\u5199\u9501\u5b9a\u65f6\uff0cFirefox \u6d4f\u89c8\u5668\u53ea\u89e6\u53d1\u4e86 `keydown` \u4e8b\u4ef6\uff0c\u4f46\u662f Chrome\u3001Safari \u548c\\n Edge \u53ea\u4f1a\u89e6\u53d1 `keyup` \u4e8b\u4ef6\uff08\u5176\u5b9e\u5c31\u76f8\u5f53\u4e8e\u5728\u5927\u5199\u5f00\u542f\u72b6\u6001\u4e0b\uff0c`Shift` \u952e\u88ab\u540c\u65f6\u6309\u4e0b\uff09\u3002"},{"id":"package-tools","metadata":{"permalink":"/blog/package-tools","source":"@site/blog/2023-04-27-package.mdx","title":"\u5f7b\u5e95\u4e86\u89e3 npm\u3001cnpm\u3001yarn\u3001pnpm \u51e0\u79cd\u5305\u7ba1\u7406\u5668","description":"\u968f\u7740\u524d\u7aef\u5de5\u7a0b\u5316\u7684\u5e94\u7528\u8d8a\u6765\u8d8a\u5e7f\uff0c\u63d2\u4ef6\u548c\u5305\u7684\u7ba1\u7406\u4e5f\u9010\u6e10\u884d\u751f\u51fa\u5f88\u591a\u7684\u7ba1\u7406\u5668\uff0c\u5e38\u89c1\u7684\u51e0\u79cd\u5305\u7ba1\u7406\u5668\u5982\uff1anpm\u3001cnpm\u3001yarn\u3001pnpm\uff0c\u90a3\u4f60\u77e5\u9053\u8fd9\u4e9b\u7ba1\u7406\u5668\u4e4b\u95f4\u6709\u54ea\u4e9b\u533a\u522b\u5417\uff1f\u6211\u4eec\u4e00\u8d77\u6765\u9010\u4e2a\u8ba4\u8bc6\u4e0b\u5b83\u4eec\uff1a","date":"2023-04-27T00:00:00.000Z","formattedDate":"2023\u5e744\u670827\u65e5","tags":[{"label":"\u5305\u7ba1\u7406\u5668","permalink":"/blog/tags/\u5305\u7ba1\u7406\u5668"},{"label":"npm","permalink":"/blog/tags/npm"},{"label":"yarn","permalink":"/blog/tags/yarn"}],"readingTime":4.27,"hasTruncateMarker":true,"authors":[{"name":"Timfan","title":"\u9ad8\u7ea7\u524d\u7aef\u5f00\u53d1","url":"https://github.com/fantingsheng","email":"fants0230@sina.com","imageURL":"https://avatars.githubusercontent.com/u/6924543?s=48&v=4","key":"timfan"}],"frontMatter":{"slug":"package-tools","title":"\u5f7b\u5e95\u4e86\u89e3 npm\u3001cnpm\u3001yarn\u3001pnpm \u51e0\u79cd\u5305\u7ba1\u7406\u5668","authors":["timfan"],"tags":["\u5305\u7ba1\u7406\u5668","npm","yarn"]},"prevItem":{"title":"JavaScript \u5b9e\u73b0\u952e\u76d8\u5927\u5199\u952e\u7684\u4fa6\u542c","permalink":"/blog/detecting-caps-lock"}},"content":"\u968f\u7740\u524d\u7aef\u5de5\u7a0b\u5316\u7684\u5e94\u7528\u8d8a\u6765\u8d8a\u5e7f\uff0c\u63d2\u4ef6\u548c\u5305\u7684\u7ba1\u7406\u4e5f\u9010\u6e10\u884d\u751f\u51fa\u5f88\u591a\u7684\u7ba1\u7406\u5668\uff0c\u5e38\u89c1\u7684\u51e0\u79cd\u5305\u7ba1\u7406\u5668\u5982\uff1anpm\u3001cnpm\u3001yarn\u3001pnpm\uff0c\u90a3\u4f60\u77e5\u9053\u8fd9\u4e9b\u7ba1\u7406\u5668\u4e4b\u95f4\u6709\u54ea\u4e9b\u533a\u522b\u5417\uff1f\u6211\u4eec\u4e00\u8d77\u6765\u9010\u4e2a\u8ba4\u8bc6\u4e0b\u5b83\u4eec\uff1a\\n\\n### npm\\n\\n[npm](https://github.com/npm/cli) \u662f Node.js \u81ea\u5e26\u7684\u5305\u7ba1\u7406\u5668\uff0c\u5e73\u65f6\u901a\u8fc7 `npm install` \u547d\u4ee4\u6765\u5b89\u88c5\u5404\u79cd npm \u5305\uff08\u6bd4\u5982\uff1a`npm install vue-router` \uff09\uff0c\u5c31\u662f\u901a\u8fc7\u8fd9\u4e2a\u5305\u7ba1\u7406\u5668\u6765\u5b89\u88c5\u7684\u3002\\n\\n\u5173\u4e8e npm \u5305\u4e0b\u8f7d\u955c\u50cf\u6e90\u7684\u8bbe\u7f6e\uff1a\\n\\n```bash\\n# \u67e5\u770b\u4e0b\u8f7d\u6e90\\nnpm config get registry\\n\\n# \u7ed1\u5b9a\u4e0b\u8f7d\u6e90\\nnpm config set registry https://registry.npmmirror.com\\n\\n# \u5220\u9664\u4e0b\u8f7d\u6e90\\nnpm config rm registry\\n```\\n\\nnpm \u7684 \u5305\u7684\u7248\u672c\u9501\u5b9a\u6587\u4ef6\u662f `package-lock.json` \uff0c\u5982\u679c\u6709\u7ba1\u7406\u591a\u4eba\u534f\u4f5c\u4ed3\u5e93\u7684\u9700\u6c42\uff0c\u53ef\u4ee5\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u628a\u5b83\u6dfb\u52a0\u81f3 `.gitignore` \u6587\u4ef6\uff0c\u4fbf\u4e8e\u7edf\u4e00\u56e2\u961f\u7684\u5305\u7ba1\u7406\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n### cnpm\\n\\n[cnpm](https://github.com/cnpm/cnpm) \u662f\u963f\u91cc\u5df4\u5df4\u63a8\u51fa\u7684\u5305\u7ba1\u7406\u5de5\u5177\uff0c\u5b89\u88c5\u4e4b\u540e\u9ed8\u8ba4\u4f1a\u4f7f\u7528 https://registry.npmmirror.com \u8fd9\u4e2a\u955c\u50cf\u6e90\u3002\\n\u5b83\u7684\u5b89\u88c5\u547d\u4ee4\u548c npm \u975e\u5e38\u4e00\u81f4\uff0c\u901a\u8fc7 `cnpm install` \u547d\u4ee4\u6765\u5b89\u88c5\uff08\u6bd4\u5982 `cnpm install vue-router`\uff09\u3002\\n\u5728\u4f7f\u7528\u5b83\u4e4b\u524d\uff0c\u9700\u8981\u901a\u8fc7 npm \u547d\u4ee4\u8fdb\u884c\u5168\u5c40\u5b89\u88c5\uff1a\\n\\n```bash\\nnpm install -g cnpm\\n\\n# \u6216\u8005\\nnpm install -g cnpm --registry=https://registry.npmmirror.com\\n```\\n\\ncnpm \u4e0d\u751f\u6210 \u7248\u672c\u9501\u5b9a lock \u6587\u4ef6\uff0c\u4e5f\u4e0d\u4f1a\u8bc6\u522b\u9879\u76ee\u4e0b\u7684 lock \u6587\u4ef6\uff0c\u6240\u4ee5\u8fd8\u662f\u63a8\u8350\u4f7f\u7528 npm \u6216\u8005\u5176\u4ed6\u5305\u7ba1\u7406\u5de5\u5177\uff0c\u901a\u8fc7\u7ed1\u5b9a\u955c\u50cf\u6e90\u7684\u65b9\u5f0f\u6765\u7ba1\u7406\u9879\u76ee\u7684\u5305\u3002\\n\\n### yarn\\n\\n[yarn](https://github.com/yarnpkg/yarn) \u4e5f\u662f\u4e00\u4e2a\u5e38\u7528\u7684\u5305\u7ba1\u7406\u5de5\u5177\uff0c\u548c npm \u5341\u5206\u76f8\u4f3c\uff0c npmjs \u4e0a\u7684\u5305\uff0c\u4e5f\u4f1a\u540c\u6b65\u5230 [yarnpkg](https://yarnpkg.com/) \u3002\\n\u4e5f\u662f\u9700\u8981\u5168\u5c40\u5b89\u88c5\u624d\u53ef\u4ee5\u4f7f\u7528\uff1a\\n\\n```bash\\nnpm install -g yarn\\n```\\n\\n\u4f46\u662f\u5b89\u88c5\u547d\u4ee4\u4e0a\u4f1a\u6709\u70b9\u4e0d\u540c\uff0c yarn \u662f\u7528 `yarn add` \u4ee3\u66ff `npm install` \uff0c\u7528 `yarn remove` \u4ee3\u66ff `npm uninstall` \uff0c\u4f8b\u5982\uff1a\\n\\n```bash\\n# \u5b89\u88c5\u5355\u4e2a\u5305\\nyarn add vue-router\\n\\n# \u5b89\u88c5\u5168\u5c40\u5305\\nyarn global add typescript\\n\\n# \u5378\u8f7d\u5305\\nyarn remove vue-router\\n```\\n\\n\u800c\u4e14\u5728\u8fd0\u884c\u811a\u672c\u7684\u65f6\u5019\uff0c\u53ef\u4ee5\u76f4\u63a5\u7528 `yarn` \u6765\u4ee3\u66ff `npm run` \uff0c\u4f8b\u5982 `yarn dev` \u76f8\u5f53\u4e8e `npm run dev` \u3002\\n\u5347\u7ea7\u7684\u65f6\u5019\u7528 `yarn upgrade` \u4ee3\u66ff `npm update`\u547d\u4ee4\u3002\\nyarn \u9ed8\u8ba4\u7ed1\u5b9a\u7684\u662f https://registry.yarnpkg.com \u7684\u4e0b\u8f7d\u6e90\uff0c\u5982\u679c\u5305\u7684\u4e0b\u8f7d\u901f\u5ea6\u592a\u6162\uff0c\u4e5f\u53ef\u4ee5\u914d\u7f6e\u955c\u50cf\u6e90\uff0c\u4f46\u662f\u547d\u4ee4\u6709\u6240\u5dee\u5f02\uff1a\\n\\n```bash\\n# \u67e5\u770b\u955c\u50cf\u6e90\\nyarn config get registry\\n\\n# \u7ed1\u5b9a\u955c\u50cf\u6e90\\n\\nyarn config set registry https://registry.npmmirror.com\\n\\n# \u5220\u9664\u955c\u50cf\u6e90\uff08\u6ce8\u610f\u8fd9\u91cc\u662f delete \uff09\\nyarn config delete registry\\n```\\n\\nyarn \u7684 \u7248\u672c\u9501\u5b9a\u6587\u4ef6\u662f yarn.lock \uff0c\u5982\u679c\u6709\u7ba1\u7406\u591a\u4eba\u534f\u4f5c\u4ed3\u5e93\u7684\u9700\u6c42\uff0c\u53ef\u4ee5\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u628a\u5b83\u6dfb\u52a0\u81f3 .gitignore \u6587\u4ef6\uff0c\u4fbf\u4e8e\u7edf\u4e00\u56e2\u961f\u7684\u5305\u7ba1\u7406\u3002\\n\\n### pnpm\\n\\n[pnpm](https://github.com/pnpm/pnpm) \u662f\u5305\u7ba1\u7406\u5de5\u5177\u7684\u4e00\u4e2a\u540e\u8d77\u4e4b\u79c0\uff0c\u4e3b\u8981\u4f18\u70b9\u5728\u4e8e\u5feb\u901f\u7684\u3001\u8282\u7701\u78c1\u76d8\u7a7a\u95f4\uff0c\u5982\u679c\u4f60\u7684\u5305\u5728\u4e00\u4e2a\u9879\u76ee\u4e2d\u5df2\u7ecf\u4e0b\u8f7d\u4e86\uff0c\u5176\u5b83\u9879\u76ee\u518d\u7528\u5230\u8fd9\u4e2a\u5305\u5c31\u4e0d\u9700\u8981\u518d\u6b21\u4e0b\u8f7d\uff0c\u800c\u662f\u901a\u8fc7\u8f6f\u94fe\u63a5\u7684\u65b9\u5f0f\u5173\u8054\u3002\u7528\u6cd5\u8ddf\u5176\u4ed6\u5305\u7ba1\u7406\u5668\u5f88\u76f8\u4f3c\uff0c\u6ca1\u6709\u592a\u591a\u7684\u5b66\u4e60\u6210\u672c\uff0c npm \u548c yarn \u7684\u547d\u4ee4\u5b83\u90fd\u652f\u6301\u3002\\n\u4e5f\u662f\u5fc5\u987b\u5148\u5168\u5c40\u5b89\u88c5\u5b83\u624d\u53ef\u4ee5\u4f7f\u7528\uff1a\\n\\n```bash\\nnpm install -g pnpm\\n```\\n\\n\u76ee\u524d pnpm \u5728\u5f00\u6e90\u793e\u533a\u7684\u4f7f\u7528\u7387\u8d8a\u6765\u8d8a\u9ad8\uff0c\u5305\u62ec\u63a5\u89e6\u6700\u591a\u7684 Vue / Vite \u56e2\u961f\u4e5f\u5728\u9010\u6b65\u8fc1\u79fb\u5230 pnpm \u6765\u7ba1\u7406\u4f9d\u8d56\u3002\\npnpm \u7684\u4e0b\u8f7d\u6e90\u4f7f\u7528\u7684\u662f npm \uff0c\u6240\u4ee5\u5982\u679c\u8981\u7ed1\u5b9a\u955c\u50cf\u6e90\uff0c\u6309\u7167 npm \u7684\u65b9\u5f0f\u5904\u7406\u5c31\u53ef\u4ee5\u4e86\u3002"}]}')}}]);